      + P.banana(cx + 26, 46, 1.2) + `<rect x="166" y="16" width="6" height="70" rx="3" fill="var(--accent)" transform="rotate(14 169 50)"/>` + scatter(18, 8, P.oats, 0.8).replace(/cx="(\d+)/g, (m, x) => m);
