    if (a.base === 'toast') { o += `<g transform="translate(150 100) rotate(-8)"><rect x="-40" y="-36" width="80" height="72" rx="14" fill="#C98A3E"/><rect x="-34" y="-30" width="68" height="60" rx="11" fill="#EDC17A"/><path d="M-30 -10c10-14 50-14 60 0 0 20-10 34-30 34s-30-14-30-34z" fill="#9BC46A"/></g>` + P.eggs(152, 98, 1.6, 10) + P.lemon(222, 70, 0.9); }
